	l.seen[e.ID] = struct{}{}
	l.balances[e.Account] += e.Amount
	return nil
}

// Balance returns the balance of one account, summed from the entries so the
// cache can be cross-checked.
func (l *Ledger) Balance(account string) int64 {
	var total int64
	for _, e := range l.entries {
