			continue
		}
		total += e.Amount
		lines = append(lines, FormatEntry(e))
	}
	lines = append(lines, fmt.Sprintf("section 1 total %s", FormatAmount(total, DefaultCurrency)))
	return Section{Title: "salary #1", Lines: lines}
