import "fmt"

// Audit returns one line per account whose cached balance disagrees with
// the balance summed from the entries.
// It returns nil when every cached balance matches the summed total,
// so callers can distinguish a clean ledger from one that needs review.
// The lines are sorted by account name.
func Audit(l *Ledger) []string {
	if l == nil {
		return nil
	}
	// Accounts is already sorted, so findings come out in a stable order.
	accounts := l.Accounts()
	var problems []string
	for _, account := range accounts {
		cached := l.balances[account]
		actual := summedBalance(l, account)
		if cached == actual {
			continue
		}
		msg := fmt.Sprintf("%s: cached %d != actual %d", account, cached, actual)
		problems = append(problems, msg)
	}
	return problems
}

// summedBalance totals the posted amounts for one account by scanning
// every entry in posting order.
// It mirrors the summation inside Balance but never panics on drift,
// so Audit can report the disagreement instead of aborting.
func summedBalance(l *Ledger, account string) int64 {
	var total int64
	for _, e := range l.entries {
		if e.Account != account {
			continue
		}
		total += e.Amount
	}
	return total
}
