func summedBalances(l *Ledger) map[string]int64 {
	totals := make(map[string]int64)
	for _, e := range l.entries {
		totals[e.Account] += e.Amount
	}
	return totals
}

// formatMismatch renders one audit finding for an account.
func formatMismatch(account string, cached, actual int64) string {
	return fmt.Sprintf("%s: cached %d != actual %d", account, cached, actual)
