import (
	"fmt"
	"sort"
)

// auditMismatch describes one account whose cached balance drifted.
type auditMismatch struct {
	account string
	cached  int64
	actual  int64
}

// sumForAccount totals the posted amounts for one account.
// It reads the entry log directly so the balance cache can be checked.
func sumForAccount(entries []Entry, account string) int64 {
	var total int64
	for _, e := range entries {
		if e.Account != account {
			continue
		}
		total += e.Amount
	}
	return total
}

// Audit compares each cached account balance against the balance
// summed from the entries and returns one line per mismatch.
// The lines are sorted by account name for stable output.
// A nil ledger yields no findings.
func Audit(l *Ledger) []string {
	if l == nil {
		return nil
	}
	var bad []auditMismatch
	for account, cached := range l.balances {
		actual := sumForAccount(l.entries, account)
		if cached != actual {
			bad = append(bad, auditMismatch{account: account, cached: cached, actual: actual})
		}
	}
	sort.Slice(bad, func(i, j int) bool { return bad[i].account < bad[j].account })
	lines := make([]string, 0, len(bad))
	for _, m := range bad {
		lines = append(lines, fmt.Sprintf("%s: cached %d != actual %d", m.account, m.cached, m.actual))
	}
	return lines
}
