package ledger

import (
	"fmt"
	"sort"
)

// Audit compares the cached per-account balances against the balances
// recomputed by summing entries. It returns one human-readable line
// for every account where the two disagree.
// A nil ledger yields no findings. The result is sorted by account
// so repeated audits of the same ledger compare equal.
func Audit(l *Ledger) []string {
	if l == nil {
		return nil
	}
	// Collect the union of cached accounts and accounts seen in entries
	// so entries without a cache line are reported as well.
	seen := map[string]struct{}{}
	for _, a := range l.Accounts() {
		seen[a] = struct{}{}
	}
	for _, e := range l.Entries() {
		seen[e.Account] = struct{}{}
	}
	names := make([]string, 0, len(seen))
	for name := range seen {
		names = append(names, name)
	}
	sort.Strings(names)
	var out []string
	for _, name := range names {
		cached, ok := l.balances[name]
		actual := sumEntries(l, name)
		if !ok || cached != actual {
			out = append(out, formatMismatch(name, cached, actual))
		}
	}
	return out
}

// sumEntries returns the balance of one account summed from the entries.
func sumEntries(l *Ledger, account string) int64 {
	var total int64
	for _, e := range l.Entries() {
		if e.Account == account {
			total += e.Amount
		}
	}
	return total
}

// formatMismatch renders one audit finding for an account.
func formatMismatch(account string, cached, actual int64) string {
	return fmt.Sprintf("account %s: cached %d != actual %d", account, cached, actual)
}
