	l := sample()
	now := time.Now().UTC()
	summary := SummarizeQuarter(l, now.Year(), (int(now.Month())-1)/3+1)
	if summary.Entries != 3 {
		t.Fatalf("entries in quarter = %d, want 3", summary.Entries)
	}
