	day := time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
	_ = ApplyEntry(l, Entry{ID: "a", Account: "x", Amount: 1, Posted: day})
	_ = ApplyEntry(l, Entry{ID: "b", Account: "x", Amount: 1, Posted: day.Add(24 * time.Hour)})
